#include <iostream>
#include <vector>

int search(const std::vector<int>& data, int target) {
    int lo = 0, hi = static_cast<int>(data.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (data[mid] == target) return mid;
        if (data[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> data{1, 3, 5, 7, 9};
    std::cout << search(data, 7) << "\n";
    return 0;
}

#include <iostream>

long long fib(int n) {
    long long a = 0, b = 1;
    for (int i = 0; i < n; ++i) {
        long long next = a + b;
        a = b;
        b = next;
    }
    return a;
}

int main() {
    std::cout << fib(10) << "\n";
    return 0;
}

