#include <vector>

int main() {
    std::vector<int> v{5, 1, 4, 2};
    for (std::size_t i = 0; i + 1 < v.size(); ++i) {
        for (std::size_t j = 0; j + 1 < v.size() - i; ++j) {
            if (v[j] > v[j + 1]) {
                int t = v[j];
                v[j] = v[j + 1];
                v[j + 1] = t;
            }
        }
    }
    for (int x : v) std::cout << x << " ";
    std::cout << "\n";
    return 0;
}

